import "dotenv/config";
import { defineConfig } from "prisma/config";
import path from "node:path";

// Kept inline (not imported from src/lib/database-url.ts) because this file
// is a CLI-only entrypoint that ships independently of the Next.js bundle —
// see src/lib/database-url.ts for the runtime-client equivalent and why
// relative sqlite paths need resolving explicitly at all.
function resolveDatabaseUrl(raw: string): string {
  const rawPath = raw.replace(/^file:/, "");
  if (rawPath === ":memory:" || path.isAbsolute(rawPath)) {
    return `file:${rawPath}`;
  }
  return `file:${path.resolve(process.cwd(), rawPath)}`;
}

const rawUrl = process.env["DATABASE_URL"];

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: rawUrl ? resolveDatabaseUrl(rawUrl) : undefined,
  },
});
